$ErrorActionPreference = 'Stop'
$events = @(Get-WinEvent -FilterHashtable @{LogName='System'; StartTime=[datetime]'2026-09-22T19:00:00'; Id=@(42,107,1,506,507)} | Where-Object {$_.ProviderName -in @('Microsoft-Windows-Kernel-Power','Microsoft-Windows-Power-Troubleshooter')} | ForEach-Object { [ordered]@{time=$_.TimeCreated.ToString('o'); id=$_.Id; provider=$_.ProviderName; record_id=$_.RecordId; message=$_.Message; xml=$_.ToXml()} })
[ordered]@{captured_at=[DateTime]::UtcNow.ToString('o'); source='Windows System event log'; events=$events; note='Power-Troubleshooter reports sleep from 2026-09-22T11:22:09Z to 13:19:11Z. Kernel-Power reason is Battery. This overlaps both aborted synthesis invocations.'} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'power-events.json') -Encoding utf8NoBOM
